INSERT INTO `kb_doc` VALUES (1,'怎么签到打卡','进入员工端后，点击左侧菜单【员工签到】，浏览器会请求获取您的位置信息，请点击允许，然后点击页面上的签到按钮即可完成打卡。签到成功后系统会记录签到时间和签到地址。','签到 打卡 考勤 上班 checkin',1,1,'2026-07-15 17:02:04');
INSERT INTO `kb_doc` VALUES (2,'签到时间是怎么规定的','系统每天有两次签到：上午班签到时间为 8:30 之前，下午班签到时间为 17:30。未在规定时间内签到将记录为\"未签到\"状态。具体考勤制度请以公司行政规定为准。','签到时间 上班时间 下班时间 几点 迟到',1,1,'2026-07-15 17:02:04');
INSERT INTO `kb_doc` VALUES (3,'上午签到和下午签到有什么区别','系统将每天的考勤分为两条记录：类型 a 表示上午班签到，类型 p 表示下午班签到。两次签到相互独立，请分别在对应时间段内完成打卡。','上午 下午 类型 a p 两次',0,1,'2026-07-15 17:02:04');
INSERT INTO `kb_doc` VALUES (4,'签到显示位置解析失败怎么办','位置解析失败通常是浏览器定位精度不足导致的。建议：1) 确认浏览器已授权位置权限；2) 尽量使用支持 GPS 的设备；3) 刷新页面后重试。位置解析失败不影响签到时间的记录，如有疑问可联系管理员核实。','位置 定位 解析失败 地址 GPS',0,1,'2026-07-15 17:02:04');
INSERT INTO `kb_doc` VALUES (5,'忘记打卡漏签了怎么办','如果当天忘记签到，签到状态会显示为\"未签到\"。请联系管理员说明情况，管理员可在管理端对您的签到状态进行审批修正（通过/驳回）。','忘记 漏签 补卡 补签 没打卡',1,1,'2026-07-15 17:02:04');
INSERT INTO `kb_doc` VALUES (6,'签到状态待审批是什么意思','当您的签到记录需要管理员确认时（如补签申请），状态会显示为待审批。管理员会在管理端进行审批操作，审批通过后状态会更新为\"已签到\"。','待审批 审批 状态 通过 驳回',0,1,'2026-07-15 17:02:04');
INSERT INTO `kb_doc` VALUES (7,'怎么查看我的签到记录','点击左侧菜单【签到记录】，可以分页查看自己的全部签到历史，包括签到日期、签到类型（上午/下午）、签到状态和签到地址。','查看 签到记录 历史 考勤记录 查询',1,1,'2026-07-15 17:02:04');
INSERT INTO `kb_doc` VALUES (8,'忘记密码怎么办','员工端暂不支持自助找回密码。请联系管理员，由管理员在后台为您重置密码，重置后请尽快登录并修改为自己的新密码。','忘记密码 找回密码 重置密码',1,1,'2026-07-15 17:02:04');
INSERT INTO `kb_doc` VALUES (9,'怎么修改密码','点击左侧菜单【修改密码】，输入旧密码和新密码，确认后提交即可。修改成功后下次登录请使用新密码。为了账号安全，建议定期更换密码。','修改密码 改密 换密码 密码安全',1,1,'2026-07-15 17:02:04');
INSERT INTO `kb_doc` VALUES (10,'怎么修改个人信息','点击左侧菜单【个人信息】，可以查看并编辑自己的出生日期、家庭住址等信息。姓名、工号、部门、职务由管理员维护，如需变更请联系人事管理员。','个人信息 修改资料 生日 住址 编辑',0,1,'2026-07-15 17:02:04');
INSERT INTO `kb_doc` VALUES (11,'工号是什么在哪里看','工号是您登录系统使用的员工编号，由管理员在录入员工信息时分配。您可以在【个人信息】页面查看自己的工号。登录时请使用工号 + 密码。','工号 员工编号 账号 登录名',0,1,'2026-07-15 17:02:04');
INSERT INTO `kb_doc` VALUES (12,'怎么请假','请假需要提交请假申请单，注明请假开始时间、结束时间和请假事由，提交后由管理员审批。审批结果分为\"已批准\"和\"已拒绝\"，请提前安排好工作交接。','请假 休假 请假流程 申请 事假 病假',1,1,'2026-07-15 17:02:04');
INSERT INTO `kb_doc` VALUES (13,'请假审批结果在哪里看','请假单提交后，管理员会进行审批。审批状态包括\"已批准\"和\"已拒绝\"。如需查询审批进度或结果，请联系您的部门管理员确认。','请假 审批结果 进度 批准 拒绝',0,1,'2026-07-15 17:02:04');
INSERT INTO `kb_doc` VALUES (14,'登录不上系统怎么办','请按以下步骤排查：1) 确认工号和密码输入正确（注意大小写）；2) 清除浏览器缓存后重试；3) 确认网络连接正常。若多次尝试仍无法登录，请联系管理员确认账号状态或重置密码。','登录失败 登录不了 无法登录 密码错误',1,1,'2026-07-15 17:02:04');
INSERT INTO `kb_doc` VALUES (15,'登录过期需要重新登录是为什么','为了保障账号安全，系统会话有效期为 30 分钟。超过 30 分钟无操作后，会话自动过期，需要重新登录。请注意及时保存您的操作内容。','登录过期 会话 超时 掉线 重新登录',0,1,'2026-07-15 17:02:04');
INSERT INTO `kb_doc` VALUES (16,'可以异地签到吗','系统签到时会记录您的实际位置地址，考勤是否有效以公司行政制度为准。如果出差或外勤需要异地打卡，建议提前向管理员报备。','异地 出差 外勤 远程 签到位置',0,1,'2026-07-15 17:02:04');
INSERT INTO `kb_doc` VALUES (17,'签到地址显示不准确怎么办','签到地址由浏览器定位解析得到，精度受设备和网络环境影响。建议使用支持 GPS 定位的设备，并在浏览器弹出位置授权时选择\"精确位置\"。地址轻微偏差不影响签到记录的有效性。','地址不准 定位不准 位置偏差 漂移',0,1,'2026-07-15 17:02:04');
INSERT INTO `kb_doc` VALUES (18,'部门或职务信息显示错误怎么办','员工的部门和职务信息由管理员统一维护，员工端不能自行修改。如发现信息有误，请联系人事管理员在管理端进行调整。','部门 职务 岗位 信息错误 调整',0,1,'2026-07-15 17:02:04');
INSERT INTO `kb_doc` VALUES (19,'系统支持哪些浏览器','推荐使用 Chrome、Edge 等现代浏览器的最新版本。签到功能依赖浏览器的地理定位能力，请确保浏览器版本不要过旧，并允许网站获取位置信息。','浏览器 兼容 chrome edge 支持',0,1,'2026-07-15 17:02:04');
INSERT INTO `kb_doc` VALUES (20,'AI客服能帮我做什么','我是 OA 办公系统的 AI 智能客服，可以解答系统使用相关的问题，例如：怎么签到打卡、怎么查看签到记录、忘记密码怎么办、怎么请假等。直接输入您的问题即可，我会从知识库中为您匹配最佳答案。','AI 客服 智能 助手 功能 帮助',0,1,'2026-07-15 17:02:04');
INSERT INTO `kb_doc` VALUES (21,'怎么联系人工客服','如果 AI 客服无法解决您的问题，请联系：1) 您的部门管理员；2) 行政部前台；3) 系统管理员（负责账号与考勤数据问题）。工作时间为工作日 8:30 - 17:30。','人工 客服 联系 电话 管理员',1,1,'2026-07-15 17:02:04');
INSERT INTO `kb_doc` VALUES (22,'怎么退出登录','点击页面右上角的【退出登录】按钮，确认后即可安全退出系统并返回登录页。在公共电脑上使用后请务必退出登录，防止账号被他人使用。','退出 登出 注销 安全退出',0,1,'2026-07-15 17:02:04');
